    def residual(rate):
        a = basis(u, rate)
        return (a @ _lstsq(a, v) - v).ravel()

    rate = least_squares(residual, [start], bounds=bounds, gtol=1e-12).x
    return basis(z, rate) @ _lstsq(basis(u, rate), v)


